// DeleteUniqueIndexCache 删除索引存在的缓存
func (u *UserCouponRepo) DeleteIndexCache(ctx context.Context, data ...*yanxue_model.UserCoupon) error {
	KeyMap := make(map[string]struct{})
	keys := make([]string, 0)
	keys = append(keys, u.cache.Key(CacheUserCouponByConditionPrefix))
	for _, item := range data {
		if item != nil {
			KeyMap[u.cache.Key(CacheUserCouponByIDPrefix, item.ID)] = struct{}{}
			KeyMap[u.cache.Key(CacheUserCouponByClaimTimePrefix, item.ClaimTime)] = struct{}{}
			KeyMap[u.cache.Key(CacheUserCouponByCouponIDPrefix, item.CouponID)] = struct{}{}
			KeyMap[u.cache.Key(CacheUserCouponByCouponNamePrefix, item.CouponName)] = struct{}{}
			KeyMap[u.cache.Key(CacheUserCouponByExpireTimePrefix, item.ExpireTime)] = struct{}{}
			KeyMap[u.cache.Key(CacheUserCouponByPhPrefix, item.Ph)] = struct{}{}
			KeyMap[u.cache.Key(CacheUserCouponByUserIDCouponIDPrefix, item.UserID, item.CouponID)] = struct{}{}
			KeyMap[u.cache.Key(CacheUserCouponByUserIDPrefix, item.UserID)] = struct{}{}
		}
	}
	for item := range KeyMap {
		keys = append(keys, item)
	}
	err := u.cache.DelBatch(ctx, keys)
	if err != nil {
		return err
	}
	return nil
}
